def render_header(targets: List[Path], is_system_scan: bool) ->Text:
    version = get_safety_version()
    timestamp = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%d %H:%M:%S %Z")

    if is_system_scan:
        header_text = f"Safety {version} running system scan"
    else:
        if targets:
            target_str = ", ".join([str(t) for t in targets])
            header_text = f"Safety {version} scanning {target_str}"
        else:
            header_text = f"Safety {version} scanning"

    header_text += f"\n{timestamp}"

    return Text(header_text)
